    public void applyDiscount(String orderId, String percent) {
        BigDecimal rate = parsePercent(percent);
        Order order = orders.get(orderId);
        Money total = order.total();
        BigDecimal discount = BigDecimal.valueOf(total.minorUnits())
                .multiply(rate)
                .movePointLeft(2)
                .setScale(0, RoundingMode.HALF_UP);
        order.changeTotal(total.minus(new Money(discount.longValueExact(), total.currency())));
    }

    private static BigDecimal parsePercent(String percent) {
        if (null == percent) {
            throw new IllegalArgumentException("percent is required");
        }
        BigDecimal rate;
        try {
            rate = new BigDecimal(percent.trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("not a percentage: " + percent, e);
        }
        if (rate.signum() < 0 || rate.compareTo(HUNDRED) > 0) {
            throw new IllegalArgumentException("percent must be between 0 and 100: " + percent);
        }
        return rate;
    }

